mapper.select:
WITH temp_table AS (

    SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR}
    MIX_AREA,#{data.machineCode,jdbcType= VARCHAR} MACHINE_CODE,#{data.glue,jdbcType= VARCHAR}
    GLUE 

)
select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy,
now() createTime
from t_machine_glue_decompose m
inner join temp_table t on m.MIX_AREA = t.MIX_AREA and m.MACHINE_CODE = t.MACHINE_CODE and m.GLUE = t.GLUE and
m.del_flag ='0'

SELECT mgd.id, mgd.mix_area, mgd.machine_code, mm.machine_name, glue, mother_glue1, mother_glue2, mother_glue3, mother_glue4, mother_glue5, mother_glue6, mother_glue7, mother_glue8, mother_glue9, mgd.remark, mgd.del_flag, mgd.create_by, mgd.create_time, mgd.update_by, mgd.update_time FROM t_machine_glue_decompose mgd, t_mix_machine mm WHERE mgd.del_flag = '0' and mm.del_flag = '0' AND mgd.mix_area = mm.mix_area AND mgd.machine_code = mm.machine_code and mgd.mix_area = #{mixArea} and mgd.machine_code = #{machineCode} and INSTR(glue, #{glue}) > 0
order by create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{data.mixArea,jdbcType= VARCHAR} MIX_AREA, #{data.glue,jdbcType=VARCHAR} glue, #{data.machineName,jdbcType= VARCHAR} MACHINE_NAME,#{rowNumber} row_numbers
) select m.recipe_equip_code machineCode from ( select distinct tmpr.recipe_material_name, tmpr.recipe_equip_code, tmpr.mix_area, tmi.machine_name from t_mes_pmt_recipe tmpr left join (select mix_area, machine_code, machine_name from t_mix_machine where del_flag = 0 union select mix_area, machine_code, machine_name from t_lhfl_machine where del_flag = 0) tmi on tmpr.recipe_equip_code = tmi.machine_code and tmpr.mix_area = tmi.mix_area where tmpr.del_flag = 0 AND tmpr.RECIPE_STATE = '1' /*配方状态: 在用*/ AND tmpr.AUDIT_FLAG = '1' /*审核标志： 已审核*/ ) m right join temp_table t on m.MIX_AREA=t.MIX_AREA and m.MACHINE_NAME = t.MACHINE_NAME and m.recipe_material_name = t.glue order by t.row_numbers

mapper.insert:
insert into t_machine_glue_decompose (id,mix_area,machine_code,glue,mother_glue1,mother_glue2,mother_glue3,mother_glue4,mother_glue5,mother_glue6,mother_glue7,mother_glue8,mother_glue9,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{machineGlueDecompose.mixArea,jdbcType= VARCHAR} mix_area, #{machineGlueDecompose.machineCode,jdbcType= VARCHAR} machine_code, #{machineGlueDecompose.glue,jdbcType= VARCHAR} glue, #{machineGlueDecompose.motherGlue1,jdbcType= VARCHAR} mother_glue1, #{machineGlueDecompose.motherGlue2,jdbcType= VARCHAR} mother_glue2, #{machineGlueDecompose.motherGlue3,jdbcType= VARCHAR} mother_glue3, #{machineGlueDecompose.motherGlue4,jdbcType= VARCHAR} mother_glue4, #{machineGlueDecompose.motherGlue5,jdbcType= VARCHAR} mother_glue5, #{machineGlueDecompose.motherGlue6,jdbcType= VARCHAR} mother_glue6, #{machineGlueDecompose.motherGlue7,jdbcType= VARCHAR} mother_glue7, #{machineGlueDecompose.motherGlue8,jdbcType= VARCHAR} mother_glue8, #{machineGlueDecompose.motherGlue9,jdbcType= VARCHAR} mother_glue9, #{machineGlueDecompose.remark,jdbcType= VARCHAR} remark, #{machineGlueDecompose.delFlag,jdbcType= VARCHAR} del_flag, #{machineGlueDecompose.createBy,jdbcType= VARCHAR} create_by, #{machineGlueDecompose.createTime,jdbcType=TIMESTAMP} create_time, #{machineGlueDecompose.updateBy,jdbcType= VARCHAR} update_by, #{machineGlueDecompose.updateTime,jdbcType=TIMESTAMP} update_time
) x
